import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P18-Codex/02-ChatGPT-Plus-Chain-Card.html","title":"01-不用代充、不买虚拟卡！用自己的国内银行卡订阅 ChatGPT Plus","lang":"zh-CN","frontmatter":{"title":"01-不用代充、不买虚拟卡！用自己的国内银行卡订阅 ChatGPT Plus","icon":"blog","date":"2026-07-17T19:49:24.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"用国内银行卡订阅 ChatGPT Plus用国内银行卡订阅 ChatGPT Plus 你好，我是悦创。 如果你实在看教程不会，可以找我付费操作！费用视你准备的情况而定！ 这篇教程解决的就是：人在 ChatGPT 不能直接完成开通的地区，如何用自己的账号和国内银行卡，把 Plus 真正订阅成功。 想用自己的账号、自己的手机和国内银行发行的银行卡开通 Ch...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"01-不用代充、不买虚拟卡！用自己的国内银行卡订阅 ChatGPT Plus\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2026-07-17T19:49:24.000Z\\",\\"dateModified\\":\\"2026-07-19T14:43:00.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/Python-Programming-Course/P18-Codex/02-ChatGPT-Plus-Chain-Card.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"01-不用代充、不买虚拟卡！用自己的国内银行卡订阅 ChatGPT Plus"}],["meta",{"property":"og:description","content":"用国内银行卡订阅 ChatGPT Plus用国内银行卡订阅 ChatGPT Plus 你好，我是悦创。 如果你实在看教程不会，可以找我付费操作！费用视你准备的情况而定！ 这篇教程解决的就是：人在 ChatGPT 不能直接完成开通的地区，如何用自己的账号和国内银行卡，把 Plus 真正订阅成功。 想用自己的账号、自己的手机和国内银行发行的银行卡开通 Ch..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-07-19T14:43:00.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2026-07-17T19:49:24.000Z"}],["meta",{"property":"article:modified_time","content":"2026-07-19T14:43:00.000Z"}]]},"git":{"createdTime":1784288838000,"updatedTime":1784472180000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":16,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"156341e0523f82d528c7cb53dc76f43062e10dc4","time":1784472180000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Codex 使用情况和计费显示 Plus"},{"hash":"3bac178c156b9002828f1874955e4976a40281d5","time":1784471308000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"04a-google-payments-add-card-form"},{"hash":"72383ba48572c061ad9756561f8736232d9becc6","time":1784471218000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"04a-google-payments-add-card-form"},{"hash":"55f6c1ff87bd11e69cb20c9ebf6dc9471550a54a","time":1784471139000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":""},{"hash":"b421c041353813460ad3670fc0f25eeb268a0fc8","time":1784470961000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":""},{"hash":"eaf4c4fb93f0475d4b8b60bddeab16fe6ec2cb48","time":1784470904000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"178294b5c91d1ee198ba7d8cdbc7a33862b8765f","time":1784469925000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"de53ef6a959d895252b0861b1a31763291a022b9","time":1784469434000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"1239add3b65a2e9c58f96fb8664107fb704f729a","time":1784468880000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add new images for ChatGPT Plus Chain Card documentation"},{"hash":"608455b826bfb5ae14a6f5ebe2622646cbf47c0c","time":1784450990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"https://us06web.zoom.us/j/81450202372\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://us06web.zoom.us/j/81450202372</a>"},{"hash":"63280d73ac95fb43f7c80da849d4c2cca6ee0b9f","time":1784354680000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新 ChatGPT Plus 订阅教程，添加多张付款方式相关图片"},{"hash":"753c3ad51aa3e1349bc965bff60cb87d0a131f6c","time":1784297377000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新 ChatGPT Plus 订阅教程，添加付款方式说明及相关图片"},{"hash":"55326e49566a8faf3f1aac611ab3b6af41523356","time":1784289470000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"https://us06web.zoom.us/j/85326780765\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://us06web.zoom.us/j/85326780765</a>"},{"hash":"9c9db60d46938f7177f9f4ee1239712eada08800","time":1784289201000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add tutorial for subscribing to ChatGPT Plus using domestic bank cards via Google Play"},{"hash":"a81e6be495162c56cd899cad869ca34fefec6c35","time":1784289040000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial CSS styles for the Python Programming Course documentation"},{"hash":"1624c76dd8e33b8a9bb998d3546016ab7bdcdc45","time":1784288838000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add tutorial for subscribing to ChatGPT Plus using domestic bank cards via Google Play"}]},"readingTime":{"minutes":21.83,"words":6549},"filePathRelative":"column/Python-Programming-Course/P18-Codex/02-ChatGPT-Plus-Chain-Card.md","excerpt":"<figure><figcaption>用国内银行卡订阅 ChatGPT Plus</figcaption></figure>\\n<p>你好，我是悦创。</p>\\n<p><strong>如果你实在看教程不会，可以找我付费操作！费用视你准备的情况而定！</strong></p>\\n<p>这篇教程解决的就是：<strong>人在 ChatGPT 不能直接完成开通的地区，如何用自己的账号和国内银行卡，把 Plus 真正订阅成功。</strong></p>\\n<p>想用自己的账号、自己的手机和国内银行发行的银行卡开通 ChatGPT Plus，可以走下面这条路径：<strong>国内银行卡 → Google 付款中心 → Google Play → ChatGPT Android 客户端 → Plus</strong>。</p>","autoDesc":true}`),a={name:`02-ChatGPT-Plus-Chain-Card.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/cover-faithful-CyiQtTpm.png" alt="用国内银行卡订阅 ChatGPT Plus" tabindex="0" loading="lazy"><figcaption>用国内银行卡订阅 ChatGPT Plus</figcaption></figure><p>你好，我是悦创。</p><p><strong>如果你实在看教程不会，可以找我付费操作！费用视你准备的情况而定！</strong></p><p>这篇教程解决的就是：<strong>人在 ChatGPT 不能直接完成开通的地区，如何用自己的账号和国内银行卡，把 Plus 真正订阅成功。</strong></p><p>想用自己的账号、自己的手机和国内银行发行的银行卡开通 ChatGPT Plus，可以走下面这条路径：<strong>国内银行卡 → Google 付款中心 → Google Play → ChatGPT Android 客户端 → Plus</strong>。</p><p>它和在 ChatGPT 网页端直接填卡不是一回事。网页端会根据银行卡的 BIN 码识别发卡地区，国内银行发行的卡即使是 Visa 或 Mastercard 单标卡，也会被直接拒绝；Google Play 对可添加的卡种相对宽松，因此可以由 Google Play 完成 Android 应用内订阅。</p><p>Google Play 在这里相当于中间付款渠道。本次实测没有额外的平台手续费；除 Plus 月费外，新增成本只有办理招行万事达人民币 IC 借记卡时支付的 5 元工本费。</p><p>这套流程最关键的不是某一个按钮，而是同时准备好四样东西：</p><ol><li>能解锁 ChatGPT 的美国网络节点；（联系我新上市的书《<strong>编程启蒙：思维与代码</strong>》➕好评：就<strong>送全球上网一年</strong>，其它平台购买无法赠送一年，只能赠送 1 个月。）</li><li>美区 Google Play 和对应的 Google Payments 付款资料；</li><li>Google Play 可以接受的 Visa/Mastercard 单标卡；</li><li>已安装官方 ChatGPT 应用的 Android 手机。</li></ol><figure><img src="/assets/image-20260717192033142-DHXH6vZc.png" alt="国内银行卡通过 Google Play 订阅 ChatGPT Plus 的付款链路" tabindex="0" loading="lazy"><figcaption>国内银行卡通过 Google Play 订阅 ChatGPT Plus 的付款链路</figcaption></figure><p><em>完整链路：国内银行卡 → Google Play → ChatGPT Android 客户端。</em></p><p>下面按完整顺序操作。</p><h2 id="一、先准备能正常使用-chatgpt-的网络环境" tabindex="-1"><a class="header-anchor" href="#一、先准备能正常使用-chatgpt-的网络环境"><span>一、先准备能正常使用 ChatGPT 的网络环境</span></a></h2><p>能打开 Google，不代表同一个节点一定能正常使用 ChatGPT。ChatGPT 对 IP 质量的要求通常更严格，所以不要只用“Google 能不能打开”作为判断标准。</p><h3 id="_1-在-clash-verge-中选择美国节点" tabindex="-1"><a class="header-anchor" href="#_1-在-clash-verge-中选择美国节点"><span>1. 在 Clash Verge 中选择美国节点</span></a></h3><p>打开 Clash Verge，进入代理节点列表，选择一个美国节点，并确保系统代理已经启用。</p><p>之所以优先使用美国节点，是因为后续要创建美区 Google Payments 资料、确认 Google Play 美区内容，网络地区和付款资料地区需要保持一致。</p><figure><img src="/assets/image-20260717191408633-r30JOxtE.png" alt="Clash Verge 的 AI 服务解锁测试" tabindex="0" loading="lazy"><figcaption>Clash Verge 的 AI 服务解锁测试</figcaption></figure><p><em>先确认 ChatGPT Web、ChatGPT iOS、Claude 等服务显示可用；失败时更换美国节点再测。</em></p><h3 id="_2-使用-clash-verge-的-ai-解锁测试" tabindex="-1"><a class="header-anchor" href="#_2-使用-clash-verge-的-ai-解锁测试"><span>2. 使用 Clash Verge 的 AI 解锁测试</span></a></h3><p>Clash Verge 的相关版本或扩展中通常带有 AI 服务解锁测试，可以一键检查 GPT、Claude 等服务是否可用。</p><p>运行测试后重点看 ChatGPT/GPT 项：</p><ul><li>如果显示可用或解锁成功，再继续；</li><li>如果显示失败，先更换另一个美国节点；</li><li>更换后重新测试，直到 ChatGPT 可以正常打开和登录。</li></ul><p>这里不要省略测试。后面即使 Google Play 已经变成美区，如果节点不能正常访问 ChatGPT，安装和付款完成后仍然可能无法使用。</p><h2 id="二、注册或登录自己的-chatgpt-账号" tabindex="-1"><a class="header-anchor" href="#二、注册或登录自己的-chatgpt-账号"><span>二、注册或登录自己的 ChatGPT 账号</span></a></h2><p>打开 ChatGPT 官网，点击注册或登录。</p><p>常见方式包括：</p><ul><li>电子邮箱注册；</li><li>使用 Google 账号继续；</li><li>使用 Apple 账号继续。</li></ul><p>国内的 163 邮箱可以正常接收验证码，不过更推荐直接用自己长期使用的 Google 账号登录：操作更方便，后面在 Android 客户端中也容易保持账号一致。</p><p>这里我最推荐的方法，就是选择【谷歌账号】直接登录！</p><figure><img src="/assets/image-20260717192601670-BMSXwgXU.png" alt="ChatGPT 登录或注册入口" tabindex="0" loading="lazy"><figcaption>ChatGPT 登录或注册入口</figcaption></figure><p><em>可以使用 Google、Apple、手机号或邮箱登录；购买前务必确认最终要获得 Plus 的账号。</em></p><p>请牢记当前登录的是哪一个 ChatGPT 账号。Google Play 只负责收款，Plus 权益最终会落在付款时登录的 ChatGPT 账号上。账号选错后，不能靠切换 Google Play 账号把权益自动转过去。</p><p>如果还准备使用 Codex，需要单独留意手机号验证：国内手机号无法完成这里的验证，而且以后可能不止验证一次。因此应准备一个自己能长期持有、可反复接收验证码的正规海外手机号，不要依赖一次性接码。这是使用 Codex 的额外准备项，不是 Google Play 购买 Plus 的付款条件。</p><p>下一篇文章会写如何在国内，自行配置海外手机卡教程。<strong>欢迎一键三连➕关注！（附带上你的评论哦！评论越多，教程出的越快！）</strong></p><h2 id="三、为什么不直接在-chatgpt-网页端付款" tabindex="-1"><a class="header-anchor" href="#三、为什么不直接在-chatgpt-网页端付款"><span>三、为什么不直接在 ChatGPT 网页端付款</span></a></h2><p>ChatGPT 网页端通常提供银行卡和 PayPal 等付款方式，但国内银行卡在这里会遇到发卡地区识别。</p><figure><img src="/assets/image-20260717215307746-DYjyfCiq.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>银行卡卡号前六位是 BIN 码。支付系统可以通过 BIN 码识别卡组织、发卡银行和发卡地区。因此：</p><ul><li>不是把卡面换成 Visa 或 Mastercard 标识就一定能通过；</li><li>国内银行发行的 Visa/Mastercard 单标卡，在网页直付时仍可能被识别为国内发卡；</li><li>PayPal 背后同样要绑定付款方式，国内卡也可能继续被拦截。（<strong>实测过国内的 Paypal 可以绑定，但是美区的 Paypal 没试过。</strong>）</li></ul><figure><img src="/assets/image-20260717194011418-7SgxzD3w.png" alt="ChatGPT 网页端付款方式验证失败" tabindex="0" loading="lazy"><figcaption>ChatGPT 网页端付款方式验证失败</figcaption></figure><p><em>这里展示的是网页直付失败；后文改走 Google Play，不是说所有国内单标卡都不能订阅。</em></p><p>所以本文不走“ChatGPT 网页端直接填国内卡”这条路，而是把 Google Play 作为应用内订阅的付款渠道：</p><ol><li>先把银行卡添加到 Google 付款中心（也常被简称为 Google Pay 绑卡）；</li><li>从 Google Play 安装 ChatGPT；</li><li>在 ChatGPT Android 客户端里发起 Plus 订阅；</li><li>由 Google Play 向银行卡扣款。</li></ol><h2 id="四、创建美区-google-payments-付款资料" tabindex="-1"><a class="header-anchor" href="#四、创建美区-google-payments-付款资料"><span>四、创建美区 Google Payments 付款资料</span></a></h2><figure><img src="/assets/image-20260718073311806-mRIj_sRa.png" alt="中国区是看不见 GPT 这类软件的" tabindex="0" loading="lazy"><figcaption>中国区是看不见 GPT 这类软件的</figcaption></figure><p>Google Play 和 Apple App Store 类似，也区分国家和地区。不同地区能看到的应用和订阅项目可能不同。要在 Google Play 找到 ChatGPT，先把当前 Google 账号对应的商店环境准备成美区。</p><p>决定 Google Play 地区的因素主要有两个：</p><ul><li>当前 IP 所在地区；</li><li>Google Payments 付款资料的国家/地区。</li></ul><p>美国节点是必要条件，真正起决定作用的是 Google 付款资料。</p><h3 id="_1-打开-google-付款中心" tabindex="-1"><a class="header-anchor" href="#_1-打开-google-付款中心"><span>1. 打开 Google 付款中心</span></a></h3><p>在浏览器中登录准备在手机上使用的同一个 Google 账号，然后打开 <a href="https://payments.google.com/" target="_blank" rel="noopener noreferrer">Google 付款中心</a>。</p><p>进入：<strong>设置 → 付款资料 / 国家或地区</strong></p><img src="/assets/image-20260718080100543-DZLYvQPr.png" style="zoom:25%;"><p>如果这个账号从未建立过付款资料，这里可能还是空的；如果已经有其他国家或地区的付款资料，会显示现有资料。</p><figure><img src="/assets/image-20260719155210843-ChUZ5vik.png" alt="Google Play 美区由 IP 和支付资料共同决定" tabindex="0" loading="lazy"><figcaption>Google Play 美区由 IP 和支付资料共同决定</figcaption></figure><p><em>美国 IP 是必要条件，Google Payments 付款资料中的国家/地区起决定作用。</em></p><h3 id="_2-新建美国付款资料" tabindex="-1"><a class="header-anchor" href="#_2-新建美国付款资料"><span>2. 新建美国付款资料</span></a></h3><p>已有付款资料的国家/地区通常不能直接改成另一个国家。点击国家/地区旁边的编辑图标，然后选择：<strong>新建个人资料 / 创建新的付款资料</strong>。</p><figure><img src="/assets/04-google-payments-us-profile-entry-BEUwhBji.jpg" alt="Google Payments 中新建美国付款资料" tabindex="0" loading="lazy"><figcaption>Google Payments 中新建美国付款资料</figcaption></figure><p><em>已有资料的国家/地区不能直接改时，选择“新建个人资料”，国家/地区选美国（US）。</em></p><p>在国家或地区下拉菜单中选择：<strong>美国（US）</strong>。</p><figure><img src="/assets/image-20260719204049055-Cit1FnTD.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20260719204009178-CGTptyud.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_3-填写美国联系地址" tabindex="-1"><a class="header-anchor" href="#_3-填写美国联系地址"><span>3. 填写美国联系地址</span></a></h3><figure><img src="/assets/image-20260719214222314-DZNfph1p.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>接下来填写姓名和美国地址。付款资料名称可以自定义；地址可以借助地址生成工具准备一份美国免税州地址，再把各字段对应复制到表单。需要填写：</p><ul><li>姓名；</li><li>街道门牌；</li><li>城市；</li><li>州；</li><li>ZIP Code；</li><li>联系方式（页面要求时填写）。</li></ul><p>街道、城市、州和 ZIP Code 必须互相对应，不能把不同地址的字段拼在一起。后面绑卡时，账单地址继续使用这一份资料。使用免税州地址的这次付款没有额外收税，但结账页面仍会显示“税费另计”，最终金额以实际订单为准。</p><p>填写完成并保存后，在付款中心确认当前已经存在一份国家/地区为美国的付款资料。</p><figure><img src="/assets/image-20260719193333712-t867hltL.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><ul><li>美国地址生成器：<a href="https://www.meiguodizhi.com/" target="_blank" rel="noopener noreferrer">https://www.meiguodizhi.com/</a>，也可以选择 GPT 直接生成一个地址。</li><li>美国免税地址：<a href="https://usaddressgen.com/tax-free-address/" target="_blank" rel="noopener noreferrer">https://usaddressgen.com/tax-free-address/</a></li></ul><h2 id="五、确认-google-play-已经切换到美区" tabindex="-1"><a class="header-anchor" href="#五、确认-google-play-已经切换到美区"><span>五、确认 Google Play 已经切换到美区</span></a></h2><p>手机保持连接前面测试通过的美国节点，然后打开 Google Play。</p><p>依次进入：<strong>右上角头像 → 设置 → 常规 → 账号和设备偏好设置 → 国家和个人资料</strong>。</p><figure><img src="/assets/image-20260719214513984-DvVqP7Ox.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20260719215346468-BLRMpbZP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20260719215416412-YQ9rn0hf.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20260719215609212-CaFF_Wzm.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20260719215703201-Bpmq5rie.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>如果页面显示“美国”，说明当前 Google Play 已经按美区资料工作。</p><figure><img src="/assets/image-20260718075958742-BsrN-6L5.png" alt="Google Play 美区方案示意" tabindex="0" loading="lazy"><figcaption>Google Play 美区方案示意</figcaption></figure><p><em>确认美国节点和美国付款资料都已生效，再继续绑卡。</em></p><p>如果仍然显示其他地区，依次检查：</p><ol><li>手机 Google Play 登录的账号，是否就是刚才新建付款资料的账号；</li><li>美国节点是否仍然连接；</li><li>Google 付款中心是否已经保存美国资料；</li><li>完全退出 Google Play 后重新打开，再检查一次。</li></ol><p>确认商店地区后，再进入下一步绑卡。</p><h2 id="六、先选对银行卡-62-开头银联卡不能直接用" tabindex="-1"><a class="header-anchor" href="#六、先选对银行卡-62-开头银联卡不能直接用"><span>六、先选对银行卡：62 开头银联卡不能直接用</span></a></h2><figure><img src="/assets/image-20260719220303218-SFb_WFmx.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>进入 Google 付款中心：<strong>支付方式 → 添加支付方式 → 添加信用卡或借记卡</strong>。</p><figure><img src="/assets/image-20260719220432335-CWBwlRnf.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/04a-google-payments-add-card-form-BuIFdAvb.jpg" alt="Google Payments 添加信用卡或借记卡" tabindex="0" loading="lazy"><figcaption>Google Payments 添加信用卡或借记卡</figcaption></figure><p><em>路径：支付方式 → 添加支付方式 → 添加信用卡或借记卡。</em></p><p>这里不能随便拿一张国内银行卡填写，先把三类卡在两个付款渠道中的区别看清楚：</p><table><thead><tr><th>卡片类型</th><th>ChatGPT 网页端直付</th><th>美区 Google Play</th></tr></thead><tbody><tr><td>62 开头的普通银联卡</td><td>不走本文路线</td><td>无法添加</td></tr><tr><td>国内银行发行的 Visa/Mastercard 单标信用卡</td><td>会按 BIN 识别为国内发行，直付失败</td><td>可以尝试；本流程实测可用</td></tr><tr><td>招商银行万事达人民币 IC 借记卡（普卡）</td><td>不走网页直付</td><td>本流程主推荐，实测可用</td></tr></tbody></table><figure><img src="/assets/image-20260719220832159-B_s97g0u.png" alt="Google Play 对国际卡和 62 银联卡的兼容性对比" tabindex="0" loading="lazy"><figcaption>Google Play 对国际卡和 62 银联卡的兼容性对比</figcaption></figure><p><em>Google Play 可以识别 Visa/Mastercard 国际卡通道，62 开头的普通银联卡不走这条链路。</em></p><p>也就是说，关键结论不是“国内卡都不行”，而是：<strong>国内卡在 ChatGPT 网页端直付会被拦截，但指定的国内 Visa/Mastercard 单标卡可以通过 Google Play 完成订阅。</strong></p><h3 id="_1-不能用的卡" tabindex="-1"><a class="header-anchor" href="#_1-不能用的卡"><span>1. 不能用的卡</span></a></h3><p>国内常见的 <strong>62 开头银联卡</strong>，即使是储蓄卡，也不能按本文这条路径直接添加为美区 Google Play 的国际卡付款方式。</p><figure><img src="/assets/image-20260719221141625-UYGB_mgU.png" alt="国内可尝试的 Visa 或 Mastercard 单标信用卡&amp;招商银行万事达人民币 IC 借记卡普卡" tabindex="0" loading="lazy"><figcaption>国内可尝试的 Visa 或 Mastercard 单标信用卡&amp;招商银行万事达人民币 IC 借记卡普卡</figcaption></figure><h3 id="_2-第一类可尝试的卡-visa-mastercard-单标信用卡" tabindex="-1"><a class="header-anchor" href="#_2-第一类可尝试的卡-visa-mastercard-单标信用卡"><span>2. 第一类可尝试的卡：Visa/Mastercard 单标信用卡</span></a></h3><p>第一类是国内银行发行、卡面只有 Visa 或 Mastercard 标识、不带银联标识的单标信用卡。</p><p>例如：</p><ul><li>招商银行全币种 Visa 信用卡（卡面产品名为“全币种国际芯片卡”）；</li><li>工商银行星座 Visa 信用卡；</li><li>其他国内银行发行的 Visa/Mastercard 单标信用卡。</li></ul><p><em>关键是单标：卡面只有 Visa 或 Mastercard 标识，不带银联标识。</em></p><p>这类信用卡可以尝试添加到 Google Play，但申请信用卡有审核门槛，从申请到拿卡也需要时间。</p><h3 id="_3-主推荐-招商银行万事达人民币-ic-借记卡-普卡" tabindex="-1"><a class="header-anchor" href="#_3-主推荐-招商银行万事达人民币-ic-借记卡-普卡"><span>3. 主推荐：招商银行万事达人民币 IC 借记卡（普卡）</span></a></h3><p>如果不想办信用卡，可以优先询问招商银行网点是否能办理：<strong>招商银行万事达人民币 IC 借记卡（普卡）</strong>。</p><p>它是人民币储蓄卡，不是信用卡。相较信用卡，办理门槛更低，线下网点可以直接申请。</p><p>申请页面可能同时出现“万事达人民币 IC 借记卡（普卡）”和“万事达金葵花卡”等产品。本文用的是前者，不要把两张卡混为一谈。</p><p>一次实际办理体验是：</p><ul><li>已经持有招行普通储蓄卡；</li><li>到招商银行网点提出办理万事达人民币借记卡；</li><li>前后约十多分钟现场拿到卡；</li><li><s>支付了 5 元制卡工本费。</s> 不需要任何工本费，马上办、马上拿。</li></ul><p>“十多分钟”是一次办理体验，不同城市、网点、客户身份和当期收费标准可能不同。出发前可以先致电网点，确认是否有卡板、需要哪些证件以及当前工本费。（不知道其它地方是否需要工本费，欢迎评论区分享！）</p><p>ChatGPT Plus 本身仍要按月支付约 20 美元；<strong>这套路径省掉的是代充费、虚拟卡费和共享账号成本</strong>。</p><figure><img src="/assets/image-20260719221551398-DEFHJQQX.png" alt="招商银行万事达人民币 IC 借记卡普卡" tabindex="0" loading="lazy"><figcaption>招商银行万事达人民币 IC 借记卡普卡</figcaption></figure><p><em>选择“万事达人民币 IC 借记卡（普卡）”，不要与“万事达金葵花卡”混淆。</em></p><h2 id="七、在招行-app-开通-万事达卡跨境线上支付" tabindex="-1"><a class="header-anchor" href="#七、在招行-app-开通-万事达卡跨境线上支付"><span>七、在招行 App 开通“万事达卡跨境线上支付”</span></a></h2><p>卡办好后不能马上默认用于境外应用内订阅。招商银行万事达人民币借记卡的跨境线上支付功能通常默认关闭，需要主动开通。</p><p>可以在办卡柜台直接让工作人员协助开通，也可以回去后在招商银行 App 中操作。</p><h3 id="app-操作路径" tabindex="-1"><a class="header-anchor" href="#app-操作路径"><span>App 操作路径</span></a></h3><ol><li>打开招商银行 App；</li><li>在首页搜索框输入 <strong>快捷支付</strong>；</li><li>进入快捷支付相关功能；</li><li>找到 <strong>万事达卡跨境线上支付</strong>；</li><li>阅读协议，按页面完成开通。</li></ol><figure><img src="/assets/image-20260719221743895-DoqVNw2a.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>如果名下有多张招行储蓄卡，页面可能默认选中了普通银联卡。此时要先切换到新办的万事达人民币借记卡，“万事达卡跨境线上支付”选项才会出现。</p><img src="/assets/image-20260719221839276-C2ME__Kd.png" alt="招商银行 App 切换到目标万事达借记卡" style="zoom:25%;"><p><em>名下有多张储蓄卡时，先切到新办的万事达人民币借记卡。</em></p><figure><img src="/assets/image-20260719221906747-CALy4qVa.png" alt="招商银行 App 中的万事达卡跨境线上支付入口" tabindex="0" loading="lazy"><figcaption>招商银行 App 中的万事达卡跨境线上支付入口</figcaption></figure><p><em>在“快捷支付”中找到“万事达卡跨境线上支付”，按页面完成开通。</em></p><h3 id="提前转入足够人民币余额" tabindex="-1"><a class="header-anchor" href="#提前转入足够人民币余额"><span>提前转入足够人民币余额</span></a></h3><p>这张卡是借记卡，Google Play 扣款时会直接从人民币账户余额中结算。</p><p>因此，绑卡和订阅前先向这张卡转入足够余额。余额至少要覆盖当月 ChatGPT Plus 订阅费，并为汇率换算和页面可能显示的税费留出余量。余额不足会导致订阅扣款失败。</p><h2 id="八、把银行卡添加到-google-付款中心" tabindex="-1"><a class="header-anchor" href="#八、把银行卡添加到-google-付款中心"><span>八、把银行卡添加到 Google 付款中心</span></a></h2><p>回到 Google 付款中心的添加银行卡页面，准备卡片背面的信息：</p><ul><li>卡号；</li><li>有效期；</li><li>CVC/CVV 安全码；</li><li>姓名；</li><li>账单地址。</li></ul><figure><img src="/assets/image-20260719223026697-BYg26Sxb.png" alt="Google Payments 银行卡信息填写表单" tabindex="0" loading="lazy"><figcaption>Google Payments 银行卡信息填写表单</figcaption></figure><p><em>依次填写卡号、有效期、CVC/CVV、姓名和前面准备的美国账单地址。</em></p><p>按下面顺序填写：</p><ol><li>输入招商银行万事达人民币借记卡的卡号；</li><li>输入卡片有效期；</li><li>输入卡背面的 CVC/CVV；</li><li>填写姓名；这一步按本流程填写即可，页面不会核对持卡人中文姓名；</li><li>账单地址选择或填写前面创建的美国付款资料地址；</li><li>提交保存。</li></ol><p>卡号、有效期、CVC/CVV、验证码和完整地址都属于敏感信息，不要截图公开，也不要发给代充人员。</p><p>添加成功后，“支付方式”页面会显示这张 Mastercard。此时银行卡已经可以被 Google Play 调用。</p><figure><img src="/assets/10-google-play-mastercard-added-9vGzNsdy.jpg" alt="Google 付款方式中已经出现 Mastercard" tabindex="0" loading="lazy"><figcaption>Google 付款方式中已经出现 Mastercard</figcaption></figure><p><em>看到 Mastercard 出现在付款方式列表，才算完成 Google Play 绑卡。</em></p><p>如果添加失败，按以下顺序检查：</p><ol><li>是否误用了 62 开头的银联卡；</li><li>是否确实是 Visa/Mastercard 单标卡；</li><li>招行 App 中是否开通“万事达卡跨境线上支付”；</li><li>是否切换到了正确的万事达借记卡；</li><li>卡内人民币余额是否足够；</li><li>卡号、有效期和 CVC/CVV 是否输入正确；</li><li>Google Payments 付款资料是否已经选择美国。</li></ol><h2 id="九、从-google-play-安装官方-chatgpt" tabindex="-1"><a class="header-anchor" href="#九、从-google-play-安装官方-chatgpt"><span>九、从 Google Play 安装官方 ChatGPT</span></a></h2><p>手机继续保持美国节点，打开 Google Play，搜索：</p><p><strong>ChatGPT</strong></p><p>进入应用详情页后，确认发布者是 <strong>OpenAI</strong>，再点击安装。不要安装名称相似的第三方客户端。</p><figure><img src="/assets/image-20260719223125029-DI3qhqAz.png" alt="Google Play 中由 OpenAI 发布的 ChatGPT 应用" tabindex="0" loading="lazy"><figcaption>Google Play 中由 OpenAI 发布的 ChatGPT 应用</figcaption></figure><p><em>核对应用名和发布者 OpenAI 后再安装。</em></p><p>安装完成后打开 ChatGPT，使用前面准备好的 ChatGPT 账号登录。推荐继续使用同一个 Google 账号一键登录，避免误入另一个账号。</p><img src="/assets/11a-chatgpt-google-login-CB2FRJG1.jpg" alt="ChatGPT Android 登录页" style="zoom:25%;"><p><em>用准备好的目标 ChatGPT 账号登录；Plus 权益会落在这个账号上。</em></p><h2 id="十、在-chatgpt-android-客户端开通-plus" tabindex="-1"><a class="header-anchor" href="#十、在-chatgpt-android-客户端开通-plus"><span>十、在 ChatGPT Android 客户端开通 Plus</span></a></h2><p>进入 ChatGPT 主界面后，找到并点击：<strong>获取 Plus / Get Plus</strong>。</p><p>然后选择：<strong>升级至 Plus</strong>。</p><figure><img src="/assets/image-20260719223250789-DV4wT8M7.png" alt="ChatGPT 主界面的获取 Plus 入口" tabindex="0" loading="lazy"><figcaption>ChatGPT 主界面的获取 Plus 入口</figcaption></figure><p><em>进入 App 后点击左上方“获取 Plus”。</em></p><figure><img src="/assets/image-20260719223312411-Bia0RdER.png" alt="ChatGPT Plus 套餐页" tabindex="0" loading="lazy"><figcaption>ChatGPT Plus 套餐页</figcaption></figure><p><em>切到 Plus，查看权益后点击“升级至 Plus”。</em></p><p>系统随后会弹出 Google Play 订阅确认页。核对：</p><ul><li>商品是 ChatGPT Plus；</li><li>付款 Google 账号正确；</li><li>付款卡是刚才添加的 Mastercard；</li><li>计费周期是每月；</li><li>自动续费时间和金额已经看清。</li></ul><p>一次实际付款页面显示的是 <strong>US$19.99/月</strong>。页面还提示：Google Play 最多可能在续订日前两天发起预授权，这不等于提前两天完成续费。当次招商银行 App 显示一笔 <strong>¥135.06 的境外消费预授权</strong>。这两个金额只代表当次支付示例，实际人民币金额会随汇率、Google Play 定价和税费变化。</p><figure><img src="/assets/image-20260719223345530-D7ARbZh1.png" alt="Google Play ChatGPT Plus 订阅确认页" tabindex="0" loading="lazy"><figcaption>Google Play ChatGPT Plus 订阅确认页</figcaption></figure><p><em>本次页面显示 US$19.99/月，并写明税费和续订日前预授权说明。</em></p><figure><img src="/assets/image-20260719223427403-Dkfl9veH.png" alt="招商银行 135.06 元境外消费预授权" tabindex="0" loading="lazy"><figcaption>招商银行 135.06 元境外消费预授权</figcaption></figure><p><em>当次银行端显示 ¥135.06 的冻结/预授权；这不是固定人民币月费。</em></p><p>确认无误后点击 <strong>订阅</strong>，按手机要求完成密码、指纹或银行验证。出现“订阅成功”提示后，Google Play 扣款流程就完成了。</p><h2 id="十一、从-app、网页和-codex-三处验证-plus" tabindex="-1"><a class="header-anchor" href="#十一、从-app、网页和-codex-三处验证-plus"><span>十一、从 App、网页和 Codex 三处验证 Plus</span></a></h2><p>付款成功后，可以从三个位置交叉确认。</p><h3 id="_1-chatgpt-android-app" tabindex="-1"><a class="header-anchor" href="#_1-chatgpt-android-app"><span>1. ChatGPT Android App</span></a></h3><p>回到 ChatGPT 主界面，打开模型选择器或设置中的订阅详情：</p><ul><li>模型选择器会出现更多模型或思考强度选项；</li><li>账户订阅详情会显示当前为 Plus；</li><li>套餐页面会显示后续续费信息。</li></ul><img src="/assets/image-20260719223524014-jeRMRyEv.png" alt="ChatGPT App 付款后的模型与思考强度选择器" style="zoom:25%;"><p><em>模型名称会更新，重点是账号已经出现 Plus 对应的模型与思考强度选项。</em></p><figure><img src="/assets/image-20260719223547958-Ckm98zoM.png" alt="ChatGPT App 中 Plus 显示为当前套餐" tabindex="0" loading="lazy"><figcaption>ChatGPT App 中 Plus 显示为当前套餐</figcaption></figure><p><em>“Plus / 当前的套餐”是移动端最直接的生效证据。</em></p><h3 id="_2-chatgpt-网页端" tabindex="-1"><a class="header-anchor" href="#_2-chatgpt-网页端"><span>2. ChatGPT 网页端</span></a></h3><p>在浏览器中登录同一个 ChatGPT 账号：</p><ul><li>主界面的模型选择器应同步显示 Plus 对应选项；</li><li>设置或账单页面会显示当前套餐为 Plus；</li><li>可以看到下一次自动续订日期。</li></ul><figure><img src="/assets/image-20260719223720299-BgPblObk.png" alt="ChatGPT 网页端模型选择器" tabindex="0" loading="lazy"><figcaption>ChatGPT 网页端模型选择器</figcaption></figure><p><em>回到网页端，用同一个账号核对模型和思考强度。</em></p><figure><img src="/assets/image-20260719223918955-DXzfKrAc.png" alt="ChatGPT 网页端账单显示 Plus 和自动续订日期" tabindex="0" loading="lazy"><figcaption>ChatGPT 网页端账单显示 Plus 和自动续订日期</figcaption></figure><p><em>网页端账单同步显示 ChatGPT Plus 和下一次自动续订日期。</em></p><h3 id="_3-codex" tabindex="-1"><a class="header-anchor" href="#_3-codex"><span>3. Codex</span></a></h3><p>用同一个 ChatGPT 账号打开 Codex：</p><ul><li>对话框中可以查看当前可用的模型和思考强度；</li><li>在“使用详情和计费”中确认账号套餐显示为 Plus。</li></ul><figure><img src="/assets/16a-codex-model-selector-Dxatv4gK.jpg" alt="Codex 模型与思考强度选择器" tabindex="0" loading="lazy"><figcaption>Codex 模型与思考强度选择器</figcaption></figure><p><em>Codex 中可查看当前开放的模型与思考强度。</em></p><figure><img src="/assets/image-20260719224139900-BkOupNIJ.png" alt="Codex 使用情况和计费显示 Plus" tabindex="0" loading="lazy"><figcaption>Codex 使用情况和计费显示 Plus</figcaption></figure><p><em>在“使用情况和计费”中确认当前套餐为 Plus。</em></p><p>不同时间开放的模型名称和额度可能变化，所以判断订阅是否成功时，以账号中的 <strong>Plus 套餐状态</strong> 和 Google Play 订阅记录为准，不要只盯住某一个具体模型名称。</p><p>如果银行卡已经扣款，但 App 仍显示免费版，先检查：</p><ol><li>当前 ChatGPT 账号是不是付款时登录的账号；</li><li>Google Play 是否显示 ChatGPT 订阅有效；</li><li>完全退出 ChatGPT 后重新打开；</li><li>在 App 设置中尝试“恢复购买”；</li><li>再到网页端确认是否已经同步。</li></ol><h2 id="十二、续费、取消和余额管理" tabindex="-1"><a class="header-anchor" href="#十二、续费、取消和余额管理"><span>十二、续费、取消和余额管理</span></a></h2><p>这份 Plus 是通过 Google Play 购买的，所以后续订阅管理也要回到 Google Play，不能只在 ChatGPT 网页端或桌面端寻找取消入口。</p><p>手机上进入：<strong>Google Play → 右上角头像 → 付款和订阅 → 订阅 → ChatGPT</strong></p><p>在这里可以查看：</p><ul><li>当前套餐；</li><li>下次续费日期；</li><li>付款方式；</li><li>取消订阅入口；</li><li>Google Play 提供的其他管理选项。</li></ul><figure><img src="/assets/17-manage-subscription-in-google-play-BrzAXL1a.jpg" alt="ChatGPT 订阅需要在 Google Play 中管理" tabindex="0" loading="lazy"><figcaption>ChatGPT 订阅需要在 Google Play 中管理</figcaption></figure><p><em>因为购买来源是 Google Play，网页端会提示回 Google Play 更改或取消。</em></p><p>需要取消时，在下次续费扣款前点击 <strong>取消订阅</strong>，并按页面确认。删除 ChatGPT App 不等于取消订阅。</p><p>如果继续使用招商银行万事达人民币借记卡自动续费，要在下次扣款前保证卡内有足够人民币余额。借记卡余额不足时，Google Play 自动续费会失败。</p><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h2><h3 id="_1-为什么-62-开头的银联储蓄卡不行" tabindex="-1"><a class="header-anchor" href="#_1-为什么-62-开头的银联储蓄卡不行"><span>1. 为什么 62 开头的银联储蓄卡不行？</span></a></h3><p>本文使用的是 Visa/Mastercard 国际卡通道。62 开头的普通银联卡不能直接作为这套美区 Google Play 流程中的国际卡使用。</p><h3 id="_2-为什么-visa-mastercard-单标卡在-chatgpt-网页端也会失败" tabindex="-1"><a class="header-anchor" href="#_2-为什么-visa-mastercard-单标卡在-chatgpt-网页端也会失败"><span>2. 为什么 Visa/Mastercard 单标卡在 ChatGPT 网页端也会失败？</span></a></h3><p>因为网页支付会通过 BIN 码识别发卡行和发卡地区。卡面只有 Visa/Mastercard 标识，不会改变它由国内银行发行的事实。</p><h3 id="_3-为什么同一张国内单标卡在-google-play-可能可以添加" tabindex="-1"><a class="header-anchor" href="#_3-为什么同一张国内单标卡在-google-play-可能可以添加"><span>3. 为什么同一张国内单标卡在 Google Play 可能可以添加？</span></a></h3><p>ChatGPT 网页支付与 Google Play 使用的是不同的支付渠道和风控体系。本文正是让 Google Play 管理 Android 应用内订阅，而不是在 ChatGPT 网页端直接绑卡。</p><h3 id="_4-招行万事达人民币-ic-借记卡一定能现场拿到吗" tabindex="-1"><a class="header-anchor" href="#_4-招行万事达人民币-ic-借记卡一定能现场拿到吗"><span>4. 招行万事达人民币 IC 借记卡一定能现场拿到吗？</span></a></h3><p>不一定。是否有卡板、办理条件、工本费和所需时间取决于当地网点。5 元工本费和十多分钟拿卡是一次实际办理体验，出发前应先向网点确认。</p><h3 id="_5-绑卡时最容易漏掉哪一步" tabindex="-1"><a class="header-anchor" href="#_5-绑卡时最容易漏掉哪一步"><span>5. 绑卡时最容易漏掉哪一步？</span></a></h3><p>最容易漏掉的是在招行 App 中开通 <strong>万事达卡跨境线上支付</strong>，以及名下多卡时没有切换到正确的万事达借记卡。</p><h3 id="_6-¥135-06-是固定月费吗" tabindex="-1"><a class="header-anchor" href="#_6-¥135-06-是固定月费吗"><span>6. ¥135.06 是固定月费吗？</span></a></h3><p>不是。一次支付页面显示 US$19.99，当次人民币扣款为 ¥135.06；未来扣款会随汇率、Google Play 定价和税费变化。</p><h3 id="_7-可以用同一张卡订阅其他-android-应用吗" tabindex="-1"><a class="header-anchor" href="#_7-可以用同一张卡订阅其他-android-应用吗"><span>7. 可以用同一张卡订阅其他 Android 应用吗？</span></a></h3><p>卡片成功添加到 Google Play 后，技术上可以作为其他应用内购买的付款方式，但每个应用都有自己的地区、账号和订阅规则，应分别确认，不能因为 ChatGPT 支付成功就默认其他服务一定可用。</p><h2 id="最后提醒" tabindex="-1"><a class="header-anchor" href="#最后提醒"><span>最后提醒</span></a></h2><p>Google Play 菜单、银行卡风控、订阅价格和账号验证要求都可能更新，以操作时页面实际显示为准。不要向任何人泄露 Google 或 ChatGPT 密码、完整卡号、CVC/CVV、短信验证码和订单号。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,222)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};